'use strict';
(function(){const host=document.getElementById('flightView'),notice=document.getElementById('viewStatus');try{
if(!window.THREE)throw Error('渲染库未加载');const T=THREE,scene=new T.Scene();scene.background=new T.Color('#b7cbd0');scene.fog=new T.Fog('#b7cbd0',700,1900);
const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.outputColorSpace=T.SRGBColorSpace;host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','真实航空影像贴图的第一人称飞行仿真');const camera=new T.PerspectiveCamera(68,1,1,2600),lat=47.3971,lng=8.5455,z=17,n=2**z,tx=(lng+180)/360*n,ty=(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n,scale=40075016.686*Math.cos(lat*Math.PI/180)/n;let failed=0;const loader=new T.TextureLoader();loader.setCrossOrigin('anonymous');
for(let x=Math.floor(tx)-4;x<=Math.floor(tx)+4;x++)for(let y=Math.floor(ty)-4;y<=Math.floor(ty)+4;y++){const mesh=new T.Mesh(new T.PlaneGeometry(scale+.08,scale+.08),new T.MeshBasicMaterial({color:0x647764}));mesh.rotation.x=-Math.PI/2;mesh.position.set((x+.5-tx)*scale,0,(y+.5-ty)*scale);scene.add(mesh);loader.load(`https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.swissimage/default/current/3857/${z}/${x}/${y}.jpeg`,texture=>{texture.colorSpace=T.SRGBColorSpace;texture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());mesh.material.map=texture;mesh.material.color.set(0xffffff);mesh.material.needsUpdate=true;notice.textContent=failed?'部分影像未加载 · 可切换地图':'FPV 仿真 · 真实航空影像贴图';},undefined,()=>{failed++;notice.textContent='部分影像未加载 · 可切换地图'});}
let state={x:420,y:500,heading:0,altitude:60},yaw=0,pitch=38;window.flightView={update:s=>{state=s},pitch:v=>{pitch=Number(v)},capture:()=>renderer.domElement.toDataURL('image/png')};function resize(){const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(host);resize();function frame(){requestAnimationFrame(frame);const desired=state.heading*Math.PI/180;const delta=Math.atan2(Math.sin(desired-yaw),Math.cos(desired-yaw));yaw+=delta*.06;camera.position.set(state.x-450,state.altitude,state.y-330);camera.lookAt(camera.position.x+Math.sin(yaw)*100,camera.position.y-Math.tan(pitch*Math.PI/180)*100,camera.position.z-Math.cos(yaw)*100);renderer.render(scene,camera)}frame();renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();notice.textContent='飞行视图暂不可用，请使用地图';document.body.classList.add('map-expanded')});
}catch(e){notice.textContent='此设备暂不支持飞行视图，已显示地图';document.body.classList.add('map-expanded')}})();
